<?php
require __DIR__ . '/../config/auth.php'; require_admin(); require __DIR__ . '/../config/database.php';
$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$file=$_FILES['image']??null;
 if($name===''||!$file||$file['error']!==UPLOAD_ERR_OK){$error='Product name and image are required.';}else{
  $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);
  if(!isset($allowed[$mime])){$error='Only JPG, PNG, WEBP or GIF images are allowed.';}elseif($file['size']>5*1024*1024){$error='Maximum image size is 5MB.';}else{
   $filename=bin2hex(random_bytes(12)).'.'.$allowed[$mime];$dest=__DIR__.'/../uploads/'.$filename;
   if(move_uploaded_file($file['tmp_name'],$dest)){$pdo->prepare('INSERT INTO products(name,description,image) VALUES(?,?,?)')->execute([$name,$description,$filename]);$msg='Image/product uploaded successfully.';}else $error='Upload failed.';
  }
 }
}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$s=$pdo->prepare('SELECT image FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();if($p){$pdo->prepare('DELETE FROM products WHERE id=?')->execute([$id]);$path=__DIR__.'/../uploads/'.$p['image'];if(is_file($path))unlink($path);$msg='Product deleted.';}}
$list=$pdo->query('SELECT * FROM products ORDER BY created_at DESC')->fetchAll();
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Products</title><style>body{font-family:Poppins,Arial,sans-serif;background:#f4f6f8;margin:0}.wrap{width:min(1050px,92%);margin:30px auto}.top{background:#0508d0;color:#fff;padding:18px 5%}.top a{color:#fff}.form,.item{background:#fff;padding:22px;border-radius:15px;box-shadow:0 4px 15px #0001;margin-bottom:25px}.form input,.form textarea{width:100%;box-sizing:border-box;padding:12px;margin:7px 0 15px;border:1px solid #ccc;border-radius:9px}.form textarea{height:90px}.form button{background:#0508d0;color:#fff;border:0;padding:12px 18px;border-radius:9px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px}.item img{width:100%;height:180px;object-fit:cover;border-radius:10px}.delete{display:inline-block;margin-top:10px;color:#b00020;font-weight:700}@media(max-width:600px){.item img{height:220px}}</style></head><body><header class="top"><h2>Manage Website Images & Products</h2><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><form class="form" method="post" enctype="multipart/form-data"><h3>Add New Product / Image</h3><label>Product Name</label><input name="name" required placeholder="e.g. Laptop"><label>Description</label><textarea name="description" placeholder="e.g. Laptop, keyboard & adaptors"></textarea><label>Image (max 5MB)</label><input name="image" type="file" accept="image/jpeg,image/png,image/webp,image/gif" required><button type="submit">Upload Product</button><?php if($msg): ?><p style="color:green"><?=$msg?></p><?php endif;if($error): ?><p style="color:#b00020"><?=$error?></p><?php endif; ?></form><div class="grid"><?php foreach($list as $p): ?><div class="item"><img src="../uploads/<?=htmlspecialchars($p['image'])?>" alt=""><h3><?=htmlspecialchars($p['name'])?></h3><p><?=htmlspecialchars($p['description'])?></p><a class="delete" href="?delete=<?=$p['id']?>" onclick="return confirm('Delete this product and image?')">Delete</a></div><?php endforeach; ?></div></main></body></html>
